707: coap_response_t COAP_API
708: coap_proxy_forward_response(coap_session_t *session,
709:                             const coap_pdu_t *received,
710:                             coap_cache_key_t **cache_key) {
711:   int ret;
712: 
713:   coap_lock_lock(session->context, return 0);
714:   ret = coap_proxy_forward_response_lkd(session,
715:                                         received,
716:                                         cache_key);
717:   coap_lock_unlock(session->context);
718:   return ret;
719: }
