211: uint32_t
212: coap_opt_length(const coap_opt_t *opt) {
213:   uint32_t length;
214: 
215:   length = *opt & 0x0f;
216:   switch (*opt & 0xf0) {
217:   case 0xf0:
218:     coap_log_debug("illegal option delta\n");
219:     return 0;
220:   case 0xe0:
221:     ++opt;
222:   /* fall through */
223:   /* to skip another byte */
224:   case 0xd0:
225:     ++opt;
226:   /* fall through */
227:   /* to skip another byte */
228:   default:
229:     ++opt;
230:   }
231: 
232:   switch (length) {
233:   case 0x0f:
234:     coap_log_debug("illegal option length\n");
235:     return 0;
236:   case 0x0e:
237:     length = (*opt++ << 8) + 269;
238:   /* fall through */
239:   case 0x0d:
240:     length += *opt++;
241:     break;
242:   default:
243:     ;
244:   }
245:   return length;
246: }
