249: coap_opt_value(const coap_opt_t *opt) {
250:   size_t ofs = 1;
251: 
252:   switch (*opt & 0xf0) {
253:   case 0xf0:
254:     coap_log_debug("illegal option delta\n");
255:     return 0;
256:   case 0xe0:
257:     ++ofs;
258:   /* fall through */
259:   case 0xd0:
260:     ++ofs;
261:     break;
262:   default:
263:     ;
264:   }
265: 
266:   switch (*opt & 0x0f) {
267:   case 0x0f:
268:     coap_log_debug("illegal option length\n");
269:     return 0;
270:   case 0x0e:
271:     ++ofs;
272:   /* fall through */
273:   case 0x0d:
274:     ++ofs;
275:     break;
276:   default:
277:     ;
278:   }
279: 
280:   return (const uint8_t *)opt + ofs;
281: }
