54:   pdu->mid = 0;
55:   pdu->max_opt = 0;
56:   pdu->max_size = size;
57:   pdu->used_size = 0;
58:   pdu->data = NULL;
59:   pdu->body_data = NULL;
60:   pdu->body_length = 0;
61:   pdu->body_offset = 0;
62:   pdu->body_total = 0;
63:   pdu->lg_xmit = NULL;
64:   pdu->session = NULL;
