566: int
567: coap_option_check_repeatable(coap_option_num_t number) {
568:   /* Validate that the option is repeatable */
569:   switch (number) {
570:   /* Ignore list of genuine repeatable */
571:   case COAP_OPTION_IF_MATCH:
572:   case COAP_OPTION_ETAG:
573:   case COAP_OPTION_LOCATION_PATH:
574:   case COAP_OPTION_URI_PATH:
575:   case COAP_OPTION_URI_QUERY:
576:   case COAP_OPTION_LOCATION_QUERY:
577:   case COAP_OPTION_RTAG:
578:     break;
579:   /* Protest at the known non-repeatable options and ignore them */
580:   case COAP_OPTION_URI_HOST:
581:   case COAP_OPTION_IF_NONE_MATCH:
582:   case COAP_OPTION_OBSERVE:
583:   case COAP_OPTION_URI_PORT:
584:   case COAP_OPTION_OSCORE:
585:   case COAP_OPTION_CONTENT_FORMAT:
586:   case COAP_OPTION_MAXAGE:
587:   case COAP_OPTION_HOP_LIMIT:
588:   case COAP_OPTION_ACCEPT:
589:   case COAP_OPTION_BLOCK2:
590:   case COAP_OPTION_BLOCK1:
591:   case COAP_OPTION_SIZE2:
592:   case COAP_OPTION_PROXY_URI:
593:   case COAP_OPTION_PROXY_SCHEME:
594:   case COAP_OPTION_SIZE1:
595:   case COAP_OPTION_ECHO:
596:   case COAP_OPTION_NORESPONSE:
597:     coap_log_info("Option number %d is not defined as repeatable - dropped\n",
598:                   number);
599:     return 0;

600:   default:
601:     coap_log_info("Option number %d is not defined as repeatable\n",
602:                   number);
603:     /* Accepting it after warning as there may be user defineable options */
604:     break;
605:   }
606:   return 1;
607: }
