863: int
864: coap_get_data_large(const coap_pdu_t *pdu, size_t *len, const uint8_t **data,
865:                     size_t *offset, size_t *total) {
866:   assert(pdu);
867:   assert(len);
868:   assert(data);
869: 
870:   *offset = pdu->body_offset;
871:   *total = pdu->body_total;
872:   if (pdu->body_data) {
873:     *data = pdu->body_data;
874:     *len = pdu->body_length;
875:     return 1;
876:   }
877:   *data = pdu->data;
878:   if (pdu->data == NULL) {
879:     *len = 0;
880:     *total = 0;
881:     return 0;
882:   }
883: 
884:   *len = pdu->used_size - (pdu->data - pdu->token);
885:   if (*total == 0)
886:     *total = *len;
887: 
888:   return 1;
889: }
