941: /**
942:  * Advances *optp to next option if still in PDU. This function
943:  * returns the number of bytes opt has been advanced or @c 0
944:  * on error.
945:  */
946: static size_t
947: next_option_safe(coap_opt_t **optp, size_t *length, uint16_t *max_opt) {
948:   coap_option_t option;
949:   size_t optsize;
950: 
951:   assert(optp);
952:   assert(*optp);
953:   assert(length);
954: 
955:   optsize = coap_opt_parse(*optp, *length, &option);
956:   if (optsize) {
957:     assert(optsize <= *length);
958: 
959:     /* signal an error if this option would exceed the
960:      * allowed number space */
961:     if (*max_opt + option.delta > COAP_MAX_OPT) {
962:       return 0;
963:     }
964:     *max_opt += option.delta;
965:     *optp += optsize;
966:     *length -= optsize;
967:   }
968: 
969:   return optsize;
970: }
