1298: static int
1299: write_char(char **obp, size_t *len, int c, int printable) {
1300:   /* Make sure space for null terminating byte */
1301:   if (*len < 2 +1) {
1302:     return 0;
1303:   }
1304: 
1305:   if (!printable) {
1306:     const uint8_t hex[] = "0123456789abcdef";
1307:     (*obp)[0] = hex[(c & 0xf0) >> 4];
1308:     (*obp)[1] = hex[c & 0x0f];
1309:   } else {
1310:     (*obp)[0] = isprint(c) ? c : '.';
1311:     (*obp)[1] = ' ';
1312:   }
1313:   *obp += 2;
1314:   *len -= 2;
1315:   return 1;
1316: }
