298: int
299: coap_uri_into_optlist(const coap_uri_t *uri, const coap_address_t *dst,
300:                       coap_optlist_t **optlist_chain, int create_port_host_opt) {
301:   if (create_port_host_opt && !coap_host_is_unix_domain(&uri->host)) {
302:     int add_option = 0;
303: 
304:     if (dst && uri->host.length) {
305: #if !defined(WITH_LWIP) && !defined(WITH_CONTIKI)
306:       char addr[INET6_ADDRSTRLEN];
307: #else /* WITH_LWIP || WITH_CONTIKI */
308:       char addr[40];
309: #endif /* WITH_LWIP || WITH_CONTIKI */
310:       coap_optlist_t *optlist;
311: 
312:       /* Add in Uri-Host if not match (need to strip off %iface) */
313:       size_t uri_host_len = uri->host.length;
314:       const uint8_t *cp = uri->host.s;
315: 
316:       /* Unfortunately not null terminated */
317:       for (size_t i = 0; i < uri_host_len; i++) {
318:         if (cp[i] == '%') {
319:           /* %iface specified in host name */
320:           uri_host_len = i;
321:           break;
322:         }
323:       }
324: 
325:       if (coap_print_ip_addr(dst, addr, sizeof(addr)) &&
326:           (strlen(addr) != uri_host_len ||
327:            memcmp(addr, uri->host.s, uri_host_len) != 0)) {
328:         /* add Uri-Host */
329:         optlist = coap_new_optlist(COAP_OPTION_URI_HOST, uri->host.length,
330:                                    uri->host.s);
331:         if (!coap_host_is_unix_domain(&uri->host)) {
332:           coap_replace_percents(optlist);
333:           coap_replace_upper_lower(optlist);
334:         }
335:         if (!coap_insert_optlist(optlist_chain, optlist)) {
336:           return 0;
337:         }
338:       }
339:     }
340:     /* Add in UriPort if not default */
341:     switch ((int)uri->scheme) {
342:     case COAP_URI_SCHEME_HTTP:
343:     case COAP_URI_SCHEME_COAP_WS:
344:       if (uri->port != 80)
345:         add_option = 1;
346:       break;
347:     case COAP_URI_SCHEME_HTTPS:
348:     case COAP_URI_SCHEME_COAPS_WS:
349:       if (uri->port != 443)
350:         add_option = 1;
351:       break;
352:     default:
353:       if (uri->port != (coap_uri_scheme_is_secure(uri) ? COAPS_DEFAULT_PORT :
354:                         COAP_DEFAULT_PORT))
355:         add_option = 1;
356:       break;
357:     }
358:     if (add_option) {
359:       uint8_t tbuf[4];
360: 
361:       coap_insert_optlist(optlist_chain,
362:                           coap_new_optlist(COAP_OPTION_URI_PORT,
363:                                            coap_encode_var_safe(tbuf, 4,
364:                                                                 (uri->port & 0xffff)),
365:                                            tbuf));
366:     }
367:   }
368: 
369:   if (uri->path.length) {
370:     if (!coap_path_into_optlist(uri->path.s, uri->path.length, COAP_OPTION_URI_PATH,
371:                                 optlist_chain))
372:       return 0;
373:   }
374: 
375:   if (uri->query.length) {
376:     if (!coap_query_into_optlist(uri->query.s, uri->query.length, COAP_OPTION_URI_QUERY,
377:                                  optlist_chain))
378:       return 0;
379:   }
380:   return 1;
381: }
