383: int
384: coap_host_is_unix_domain(const coap_str_const_t *host) {
385:   if (host->length >= 3 && host->s[0] == '%' &&
386:       host->s[1] == '2' &&
387:       (host->s[2] == 'F' || host->s[2] == 'f')) {
388:     return 1;
389:   }
390:   if (host->length >= 1 && host->s[0] == '/')
391:     return 1;
392:   return 0;
393: }
