395: /**
396:  * Calculates decimal value from hexadecimal ASCII character given in
397:  * @p c. The caller must ensure that @p c actually represents a valid
398:  * heaxdecimal character, e.g. with isxdigit(3).
399:  *
400:  * @hideinitializer
401:  */
402: #define hexchar_to_dec(c) ((c) & 0x40 ? ((c) & 0x0F) + 9 : ((c) & 0x0F))
403: 
404: /**
405:  * Decodes percent-encoded characters while copying the string @p seg
406:  * of size @p length to @p buf. The caller of this function must
407:  * ensure that the percent-encodings are correct (i.e. the character
408:  * '%' is always followed by two hex digits. and that @p buf provides
409:  * sufficient space to hold the result. This function is supposed to
410:  * be called by make_decoded_option() only.
411:  *
412:  * @param seg     The segment to decode and copy.
413:  * @param length  Length of @p seg.
414:  * @param buf     The result buffer.
415:  */
416: static void
417: decode_segment(const uint8_t *seg, size_t length, unsigned char *buf) {
418: 
419:   while (length--) {
420: 
421:     if (*seg == '%') {
422:       *buf = (hexchar_to_dec(seg[1]) << 4) + hexchar_to_dec(seg[2]);
423: 
424:       seg += 2;
425:       length -= 2;
426:     } else {
427:       *buf = *seg;
428:     }
429: 
430:     ++buf;
431:     ++seg;
432:   }
433: }
434: 
435: /**
436:  * Runs through the given path (or query) segment and checks if
437:  * percent-encodings are correct. This function returns @c 0 on success
438:  * and @c -1 on error.
439:  */
440: static int
441: check_segment(const uint8_t *s, size_t length, size_t *segment_size) {
442:   size_t n = 0;
443: 
444:   while (length) {
445:     if (*s == '%') {
446:       if (length < 2 || !(isxdigit(s[1]) && isxdigit(s[2])))
447:         return -1;
448: 
449:       s += 2;
450:       length -= 2;
451:     }
452: 
453:     ++s;
454:     ++n;
455:     --length;
456:   }
457: 
458:   *segment_size = n;
459: 
460:   return 0;
461: }
462: 
463: /**
464:  * Writes a coap option from given string @p s to @p buf. @p s should
465:  * point to a (percent-encoded) path or query segment of a coap_uri_t
466:  * object.  The created option will have type @c 0, and the length
467:  * parameter will be set according to the size of the decoded string.
468:  * On success, this function returns @c 0 and sets @p optionsize to the option's
469:  * size. On error the function returns a value less than zero. This function
470:  * must be called from coap_split_path_impl() only.
471:  *
472:  * @param s           The string to decode.
473:  * @param length      The size of the percent-encoded string @p s.
474:  * @param buf         The buffer to store the new coap option.
475:  * @param buflen      The maximum size of @p buf.
476:  * @param optionsize  The option's size.
477:  *
478:  * @return @c 0 on success and @c -1 on error.
479:  *
480:  * @bug This function does not split segments that are bigger than 270
481:  * bytes.
482:  */
483: static int
484: make_decoded_option(const uint8_t *s, size_t length,
485:                     unsigned char *buf, size_t buflen, size_t *optionsize) {
486:   int res;
487:   size_t segmentlen;
488:   size_t written;
489: 
490:   if (!buflen) {
491:     coap_log_debug("make_decoded_option(): buflen is 0!\n");
492:     return -1;
493:   }
494: 
495:   res = check_segment(s, length, &segmentlen);
496:   if (res < 0)
497:     return -1;
498: 
499:   /* write option header using delta 0 and length res */
500:   written = coap_opt_setheader(buf, buflen, 0, segmentlen);
501: 
502:   assert(written <= buflen);
503: 
504:   if (!written)                        /* encoding error */
505:     return -1;
506: 
507:   buf += written;                /* advance past option type/length */
508:   buflen -= written;
509: 
510:   if (buflen < segmentlen) {
511:     coap_log_debug("buffer too small for option\n");
512:     return -1;
513:   }
514: 
515:   decode_segment(s, length, buf);
516: 
517:   *optionsize = written + segmentlen;
518: 
519:   return 0;
520: }
