527: typedef void (*segment_handler_t)(const uint8_t *, size_t, void *);
528: 
529: /**
530:  * Checks if path segment @p s consists of one or two dots.
531:  *
532:  * returns 1 if . , 2 if .. else 0.
533:  */
534: static int
535: dots(const uint8_t *s, size_t len) {
536:   uint8_t p;
537: 
538:   if (!len)
539:     return 0;
540: 
541:   p = *s;
542: 
543:   /* Check 'first' char */
544:   if (p == '%' && len >=3) {
545:     if (s[1] == '2' && (s[2] == 'E' || s[2] == 'e')) {
546:       s += 2;
547:       len -= 2;
548:     }
549:     p = '.';
550:   }
551:   if (p != '.')
552:     return 0;
553:   if (len == 1)
554:     return 1;
555: 
556:   /* Check 'second' char, first is '.' */
557:   s++;
558:   len--;
559:   assert(len);
560:   p = *s;
561:   if (p == '%' && len >=3) {
562:     if (s[1] == '2' && (s[2] == 'E' || s[2] == 'e')) {
563:       len -= 2;
564:     }
565:     p = '.';
566:   }
567:   if (p != '.')
568:     return 0;
569:   if (len == 1)
570:     return 2;
571: 
572:   return 0;
573: }
