575: struct cnt_str {
576:   coap_string_t base_buf;
577:   coap_string_t buf;
578:   int n;
579: };
580: 
581: static void
582: backup_segment(void *data) {
583:   struct cnt_str *state = (struct cnt_str *)data;
584:   int i;
585:   uint8_t *buf;
586: 
587:   if (state->n == 0)
588:     return;
589: 
590:   state->n--;
591:   buf = state->base_buf.s;
592:   for (i = 0; i < state->n; i++) {
593:     buf += coap_opt_size(buf);
594:   }
595:   state->buf.s = buf;
596:   state->buf.length = state->base_buf.length - (buf - state->base_buf.s);
597: }

598: 
599: /**
600:  * Splits the given string into segments. You should call one of the
601:  * functions coap_split_path() or coap_split_query() instead.
602:  *
603:  * @param path   The URI path string to be tokenized.
604:  * @param len    The length of @p path.
605:  * @param h      A handler that is called with every token.
606:  * @param data   Opaque data that is passed to @p h when called.
607:  *
608:  * @return The number of characters that have been parsed from @p s.
609:  */
610: static size_t
611: coap_split_path_impl(const uint8_t *path, size_t len,
612:                      segment_handler_t h, void *data) {
613:   const uint8_t *p, *q;
614:   size_t length = len;
615:   int num_dots;
616: 
617:   p = q = path;
618:   while (length > 0 && !strnchr((const uint8_t *)"?#", 2, *q)) {
619:     if (*q == '/') {
620:       /* start new segment */
621:       num_dots = dots(p, q - p);
622:       switch (num_dots) {
623:       case 1:
624:         /* drop segment */
625:         break;
626:       case 2:
627:         /* backup segment */
628:         backup_segment(data);
629:         break;
630:       case 0:
631:       default:
632:         /* add segment */
633:         h(p, q - p, data);
634:         break;
635:       }
636: 
637:       p = q + 1;
638:     }
639: 
640:     q++;
641:     length--;
642:   }
643: 
644:   /* write last segment */
645:   num_dots = dots(p, q - p);
646:   switch (num_dots) {
647:   case 1:
648:     /* drop segment */
649:     break;
650:   case 2:
651:     /* backup segment */
652:     backup_segment(data);
653:     break;
654:   case 0:
655:   default:
656:     /* add segment */
657:     h(p, q - p, data);
658:     break;
659:   }
660: 
661:   return q - path;
662: }
663: 
664: static void
665: write_option(const uint8_t *s, size_t len, void *data) {
666:   struct cnt_str *state = (struct cnt_str *)data;
667:   int res;
668:   size_t optionsize;
669:   assert(state);
670: 
671:   res = make_decoded_option(s, len, state->buf.s, state->buf.length, &optionsize);
672:   if (res == 0) {
673:     state->buf.s += optionsize;
674:     state->buf.length -= optionsize;
675:     state->n++;
676:   }
677: }
