709: static void
710: backup_optlist(coap_optlist_t **optlist_begin) {
711:   coap_optlist_t *last = NULL;
712:   coap_optlist_t *cur = *optlist_begin;
713: 
714:   if (!cur)
715:     return;
716: 
717:   while (cur) {
718:     if (!cur->next)
719:       break;
720:     last = cur;
721:     cur = cur->next;
722:   }
723:   coap_delete_optlist(cur);
724:   if (last) {
725:     last->next = NULL;
726:   } else {
727:     *optlist_begin = NULL;
728:   }
729: }
